#pragma once
#include <cstddef>
#include <cstdint>

// Low-battery pictures, generated by tools/lowbattery_art/generate.py.
// Each entry is a raw-deflate stream holding a 480x640 1-bit image (MSB first, bit set = ink).
namespace lowbatteryart {
constexpr int COUNT = 16;
constexpr int WIDTH = 480;
constexpr int HEIGHT = 640;
constexpr size_t RAW_BYTES = static_cast<size_t>(WIDTH / 8) * HEIGHT;

struct Entry {
  const uint8_t* data;
  size_t size;
};

extern const Entry ENTRIES[COUNT];
}  // namespace lowbatteryart
